USE db_notificaciones;
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_id VARCHAR(60) UNIQUE, event_type VARCHAR(100) NOT NULL, title VARCHAR(180) NOT NULL, message TEXT NOT NULL, severity ENUM('info','warning','critical') DEFAULT 'warning', payload JSON, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notification_deliveries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, notification_id BIGINT UNSIGNED NOT NULL UNIQUE, status ENUM('pending','sent','failed') NOT NULL DEFAULT 'pending', attempts INT NOT NULL DEFAULT 0, last_error TEXT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (notification_id) REFERENCES notifications(id)) ENGINE=InnoDB;
